/**
 * Types for the normalised official OSCA dataset (public/data/osca/),
 * generated by scripts/osca/import_osca.py from the ABS source workbooks.
 * Fields exist only where the official sources support them.
 */

export type OscaGroupLevel = "major" | "sub-major" | "minor" | "unit";
export type OscaSkillLevel = 1 | 2 | 3 | 4 | 5;

/** groups.json — group-level data (never copied into occupation records). */
export type OscaGroup = {
  code: string; // 1, 2, 3 or 4 digits
  level: OscaGroupLevel;
  title: string; // Structure Table 5 (authoritative)
  parentCode: string | null;
  skillLevels: OscaSkillLevel[]; // group level
  leadStatement: string; // group level (Category Descriptions Table 2)
  inclusionExclusion?: string; // group level
};

/** occupations-index.json — lightweight search records (occupation level). */
export type OscaOccupationIndexEntry = {
  code: string; // six digits, always a string
  principalTitle: string; // Structure Table 5, confirmed by the Titles Index
  alternativeTitles: string[]; // same meaning as the principal title
  specialisations: string[]; // a subset of jobs within the occupation
  isNec: boolean; // code ends in "99": a "not elsewhere classified" category
  /** Titles included within an nec category. These are NOT standalone occupations. */
  necIncludedTitles: string[];
  skillLevel: OscaSkillLevel; // occupation level
  unitGroupCode: string;
  minorGroupCode: string;
  subMajorGroupCode: string;
  majorGroupCode: string;
  /** Normalised official titles joined with " | " (see lib/osca/search.ts). */
  searchText: string;
};

/** occupations-details/{major}.json — heavier occupation-level text. */
export type OscaOccupationDetail = {
  leadStatement: string;
  mainTasks: string[]; // empty only for nec categories
  registrationOrLicensing?: string;
  inclusionExclusion?: string;
  skillAttributes?: string;
  /** IDs of entries in corrections.json that affected this occupation. */
  corrections?: string[];
};

export type OscaCorrectionType =
  | "whitespace-normalisation"
  | "encoding-anomaly"
  | "source-title-disagreement"
  | "code-format-normalisation";

export type OscaCorrection = {
  id: string;
  type: OscaCorrectionType;
  code: string | null;
  field: string;
  source: "structure" | "descriptions" | "index";
  table: string;
  original: string;
  corrected: string;
  reason: string;
};

/** Full occupation record = index entry + detail (assembled at runtime). */
export type OscaOccupation = Omit<OscaOccupationIndexEntry, "searchText"> & OscaOccupationDetail;
